CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 VARCHAR(10), c1  NOT NULL DEFAULT 0, c2  DEFAULT 'd', c3 BLOB DEFAULT 'd');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES(-5, 'theta', 'eta', -544.97);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES(855, 0, '日本', 4);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES('sigma', 436, x'54', 3);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 VARCHAR(10) NOT NULL DEFAULT 0, c1  COLLATE NOCASE, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, ref) VALUES(0, x'08f74d5461', 2);
INSERT OR IGNORE INTO t1(c0, c1, ref) VALUES(3.141592653589793, x'91ef473ce50e', 8);
INSERT OR IGNORE INTO t1(c0, c1, ref) VALUES(0, 282, 8);
INSERT OR IGNORE INTO t1(c0, c1, ref) VALUES(NULL, -410.61, 6);
INSERT OR IGNORE INTO t1(c0, c1, ref) VALUES('42', '', 4);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 BLOB, c1 REAL DEFAULT 'd', c2 NUMERIC UNIQUE, ref INTEGER REFERENCES t1(id));
INSERT OR IGNORE INTO t2(c0, c1, c2, ref) VALUES(NULL, x'8fd15befef', '1e3', 6);
INSERT OR IGNORE INTO t2(c0, c1, c2, ref) VALUES('0x1F', x'f19d20', -1e308, 4);
INSERT OR IGNORE INTO t2(c0, c1, c2, ref) VALUES('NULL', 'theta', -2, 6);
SELECT length('Lambda'), upper('Lambda'), lower('Lambda'), substr('Lambda', 0, 5), instr('Lambda', 'kappa'), replace('Lambda', 'a', 'XY'), trim('Lambda'), ltrim('Lambda', 'ab'), hex('Lambda'), quote('Lambda'), unicode('Lambda'), 'Lambda' LIKE 'a%', 'Lambda' GLOB '*', char(87, 822), 'Lambda' || 'kappa', 'Lambda' < 'kappa', 'Lambda' = 'kappa' COLLATE NOCASE;
SELECT length('tau'), upper('tau'), lower('tau'), substr('tau', -2, 4), instr('tau', 'nu'), replace('tau', 'é', ''), trim('tau'), ltrim('tau', 'ab'), hex('tau'), quote('tau'), unicode('tau'), 'tau' LIKE 'a%', 'tau' GLOB '?', char(75, 929), 'tau' || 'nu', 'tau' < 'nu', 'tau' = 'nu' COLLATE NOCASE;
SELECT length('señor'), upper('señor'), lower('señor'), substr('señor', 0, 2), instr('señor', 'a%b'), replace('señor', 'a', ''), trim('señor'), ltrim('señor', 'ab'), hex('señor'), quote('señor'), unicode('señor'), 'señor' LIKE 'a%', 'señor' GLOB '*[a-m]*', char(84, 495), 'señor' || 'a%b', 'señor' < 'a%b', 'señor' = 'a%b' COLLATE NOCASE;
SELECT length('it''s'), upper('it''s'), lower('it''s'), substr('it''s', 1, 3), instr('it''s', 'gamma'), replace('it''s', 'a', 'XY'), trim('it''s'), ltrim('it''s', 'ab'), hex('it''s'), quote('it''s'), unicode('it''s'), 'it''s' LIKE 'a%', 'it''s' GLOB '?', char(77, 321), 'it''s' || 'gamma', 'it''s' < 'gamma', 'it''s' = 'gamma' COLLATE NOCASE;
SELECT length('omega'), upper('omega'), lower('omega'), substr('omega', 3, 0), instr('omega', 'sigma'), replace('omega', '', 'XY'), trim('omega'), ltrim('omega', 'ab'), hex('omega'), quote('omega'), unicode('omega'), 'omega' LIKE '%é%', 'omega' GLOB '*', char(71, 371), 'omega' || 'sigma', 'omega' < 'sigma', 'omega' = 'sigma' COLLATE NOCASE;
SELECT length('it''s'), upper('it''s'), lower('it''s'), substr('it''s', 2, 2), instr('it''s', 'eta'), replace('it''s', 'é', ''), trim('it''s'), ltrim('it''s', 'ab'), hex('it''s'), quote('it''s'), unicode('it''s'), 'it''s' LIKE '_', 'it''s' GLOB '*[a-m]*', char(83, 889), 'it''s' || 'eta', 'it''s' < 'eta', 'it''s' = 'eta' COLLATE NOCASE;
SELECT length('psi'), upper('psi'), lower('psi'), substr('psi', 3, 0), instr('psi', 'rho'), replace('psi', 'é', '_'), trim('psi'), ltrim('psi', 'ab'), hex('psi'), quote('psi'), unicode('psi'), 'psi' LIKE 'a%', 'psi' GLOB '*', char(79, 811), 'psi' || 'rho', 'psi' < 'rho', 'psi' = 'rho' COLLATE NOCASE;
SELECT id, id, percent_rank() OVER (PARTITION BY id IS NULL ORDER BY id GROUPS BETWEEN 1 PRECEDING AND 1 FOLLOWING) FROM t2 ORDER BY id;
SELECT count(*), count(ref), sum(ref), total(ref), avg(ref), min(ref), max(ref), count(DISTINCT ref) FROM t1;
SELECT ref, count(*), group_concat(id) FROM (SELECT * FROM t1 ORDER BY id) GROUP BY ref ORDER BY ref;
